from ta_ue_plugin_rtg.rpc.err_protocol import ErrProtocol


class ErrJsonRpc(ErrProtocol):
    """Base class for exceptions related to JSON-RPC"""


class ErrJsonRpcError(ErrJsonRpc):
    """generic JSON-RPC error"""
    def __init__(self, err_data):
        """Init ErrJsonRpcError"""
        super(ErrJsonRpcError, self).__init__(str(err_data))
        self.err = err_data


class ErrJsonRpcDecodeError(ErrJsonRpcError):
    """ErrJsonRpcDecodeError Class"""
    def __init__(self, err_data):
        """Init ErrJsonRpcDecodeError"""
        super(ErrJsonRpcDecodeError, self).__init__(err_data)


class ErrJsonRpcNotImplemented(ErrJsonRpcError):
    """ErrJsonRpcNotImplemented Class"""
    def __init__(self, err_data):
        """Init ErrJsonRpcNotImplemented"""
        super(ErrJsonRpcNotImplemented, self).__init__(err_data)


